#nullable enable // autogenerated

using MVZ2.Audios;
using MVZ2.Resources;
using MVZ2Logic.Options;
using MVZ2Logic.Resources;
using PVZEngine;
using UnityEngine;

namespace MVZ2.Managers
{
    public partial class ResourceManager : MonoBehaviour
    {
        public ResourceContext GetResourceContext()
        {
            return new ResourceContext()
            {
                censored = !Main.OptionsManager.HasBloodAndGore(),
                languageCode = Main.LanguageManager.GetCurrentLanguage(),
            };
        }

        #region Provider
        public void AddSpriteProvider(ISpriteProvider provider) => resourceLibrary.AddSpriteProvider(provider);
        public void RemoveSpriteProvider(ISpriteProvider provider) => resourceLibrary.RemoveSpriteProvider(provider);
        public void AddTextureProvider(ITexture2DProvider provider) => resourceLibrary.AddTextureProvider(provider);
        public void RemoveTextureProvider(ITexture2DProvider provider) => resourceLibrary.RemoveTextureProvider(provider);
        public void AddAudioClipProvider(IAudioClipProvider provider) => resourceLibrary.AddAudioClipProvider(provider);
        public void RemoveAudioClipProvider(IAudioClipProvider provider) => resourceLibrary.RemoveAudioClipProvider(provider);
        public void AddSoundSourceProvider(ISoundSourceProvider provider) => resourceLibrary.AddSoundSourceProvider(provider);
        public void RemoveSoundSourceProvider(ISoundSourceProvider provider) => resourceLibrary.RemoveSoundSourceProvider(provider);
        public void AddMusicSourceProvider(IMusicSourceProvider provider) => resourceLibrary.AddMusicSourceProvider(provider);
        public void RemoveMusicSourceProvider(IMusicSourceProvider provider) => resourceLibrary.RemoveMusicSourceProvider(provider);
        public void AddFragmentSourceProvider(IFragmentSourceProvider provider) => resourceLibrary.AddFragmentSourceProvider(provider);
        public void RemoveFragmentSourceProvider(IFragmentSourceProvider provider) => resourceLibrary.RemoveFragmentSourceProvider(provider);
        public void AddTalkCharacterSourceProvider(ITalkCharacterModificationProvider provider) => resourceLibrary.AddTalkCharacterModificationProvider(provider);
        public void RemoveTalkCharacterSourceProvider(ITalkCharacterModificationProvider provider) => resourceLibrary.RemoveTalkCharacterModificationProvider(provider);
        #endregion

        #region Register
        public void RegisterSprite(SpriteReference spriteReference, Sprite sprite)
        {
            var key = new SpriteLookupKey(spriteReference);
            RegisterSprite(key, sprite);
        }
        public void RegisterSprite(SpriteLookupKey key, Sprite value) => resourceLibrary.RegisterSprite(key, value);
        public void RegisterTexture2D(ResourceLookupKey key, Texture2D value) => resourceLibrary.RegisterTexture2D(key, value);
        public void RegisterAudioClip(NamespaceID key, AudioClip value) => resourceLibrary.RegisterAudioClip(key, value);
        #endregion

        #region 获取Sprite
        public Sprite? GetSprite(SpriteReference? spriteRef) => resourceLibrary.GetSprite(spriteRef);
        public Sprite GetFinalSprite(Sprite sprite)
        {
            var spriteRef = GetSpriteReference(sprite);
            return GetFinalSprite(spriteRef) ?? sprite;
        }
        public Sprite? GetFinalSprite(SpriteReference? spriteRef)
        {
            return GetFinalSprite(spriteRef, GetResourceContext());
        }
        public Sprite GetFinalSprite(Sprite sprite, ResourceContext context) => resourceLibrary.GetFinalSprite(sprite, context);
        public Sprite? GetFinalSprite(SpriteReference? spriteRef, ResourceContext context) => resourceLibrary.GetFinalSprite(spriteRef, context);


        public Texture2D? GetTexture(ResourceLookupKey id) => resourceLibrary.GetTexture2D(id);
        public Texture2D GetFinalTexture(Texture2D texture2D)
        {
            var id = GetTexture2DKey(texture2D);
            return GetFinalTexture(id) ?? texture2D;
        }
        public Texture2D? GetFinalTexture(ResourceLookupKey? id) => resourceLibrary.GetFinalTexture(id, GetResourceContext());


        public AudioClip? GetAudioClip(NamespaceID? id) => resourceLibrary.GetAudioClip(id);
        public AudioClip? GetFinalAudioClip(NamespaceID? id) => resourceLibrary.GetFinalAudioClip(id, GetResourceContext());

        public ISoundSource? GetFinalSoundMeta(NamespaceID? id) => resourceLibrary.GetFinalSoundMeta(id, GetResourceContext());
        public IMusicSource? GetFinalMusicSource(NamespaceID? id) => resourceLibrary.GetFinalMusicSource(id, GetResourceContext());
        public IFragmentSource? GetFinalFragmentSource(NamespaceID? id) => resourceLibrary.GetFinalFragmentSource(id, GetResourceContext());
        public ITalkCharacterModification? GetFinalTalkCharacterModification(NamespaceID? id) => resourceLibrary.GetFinalTalkCharacterModification(id, GetResourceContext());
        public ITalkCharacterSource? GetFinalTalkCharacterSource(NamespaceID? characterID)
        {
            ITalkCharacterSource? characterSource = GetCharacterMeta(characterID);
            var modification = GetFinalTalkCharacterModification(characterID);
            if (characterSource != null && modification != null)
            {
                characterSource = modification.Modify(characterSource);
            }
            return characterSource;
        }
        #endregion

        #region Resource ID
        public SpriteReference? GetSpriteReference(Sprite resouce) => resourceLibrary.GetSpriteReference(resouce);
        public ResourceLookupKey? GetTexture2DKey(Texture2D resource) => resourceLibrary.GetTexture2DKey(resource);
        public NamespaceID? GetAudioClipID(AudioClip resource) => resourceLibrary.GetAudioClipID(resource);
        #endregion

        #region 初始化
        private void Init_Resolving()
        {
            resourceLibrary.Init();
            resourceLibrary.AddSoundSourceProvider(new BaseGameSoundSourceProvider(this));
            resourceLibrary.AddMusicSourceProvider(new BaseGameMusicSourceProvider(this));
            resourceLibrary.AddFragmentSourceProvider(new BaseGameFragmentSourceProvider(this));
        }
        private void ClearResources_Resolving()
        {
            resourceLibrary.Clear();
        }
        #endregion

        private ResourceLibrary resourceLibrary = new ResourceLibrary();
    }
}
